from fastapi import FastAPI
from fastapi.responses import HTMLResponse

from .api.routes import router
from .db import init_db

app = FastAPI(title="Qanas Data Engine", version="0.3.1")

@app.on_event("startup")
def startup(): init_db()

app.include_router(router, prefix="/api")

DASHBOARD_HTML = r'''<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>قنص | Reverse Split Intelligence</title><style>
:root{--bg:#071019;--panel:#0b1722;--line:#193041;--text:#edf5f8;--muted:#8296a5;--gold:#d7ad59;--gold2:#f0d18b;--green:#4bd39a;--red:#ff6b78}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:"Segoe UI",Tahoma,Arial,sans-serif}.wrap{max-width:1500px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;gap:18px;margin-bottom:22px}.brand{display:flex;align-items:center;gap:14px}.mark{width:54px;height:54px;border:1px solid #55472d;border-radius:17px;display:grid;place-items:center;font-weight:900;font-size:25px;color:var(--gold2)}h1{margin:0}.brand small,.muted{color:var(--muted)}.actions{display:flex;gap:10px}.btn{border:1px solid var(--line);background:#0d1a26;color:var(--text);padding:11px 15px;border-radius:12px;cursor:pointer;font-weight:700}.btn.gold{background:linear-gradient(135deg,#b88b3a,#e7c272);color:#10151a;border:0}.btn:disabled{opacity:.5}.hero{display:grid;grid-template-columns:1.4fr .6fr;gap:16px;margin-bottom:16px}.hero-main,.syncbox{border:1px solid var(--line);background:#0b1722;border-radius:22px;padding:22px}.hero h2{font-size:32px;margin:8px 0}.hero p{color:var(--muted)}.syncrow{display:flex;justify-content:space-between;margin:8px 0;color:var(--muted)}.syncrow strong{color:var(--text)}.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:16px}.stat{background:#0b1722;border:1px solid var(--line);border-radius:17px;padding:17px}.stat span{color:var(--muted);font-size:12px}.stat b{font-size:25px;display:block;margin-top:8px}.stat em{font-size:11px;color:#5f7788;font-style:normal}.toolbar{display:flex;gap:10px;justify-content:space-between;background:#0b1722;border:1px solid var(--line);padding:12px;border-radius:16px 16px 0 0}.search{flex:1;max-width:420px}.search input{width:100%;background:#08141e;border:1px solid #1e3546;color:var(--text);border-radius:11px;padding:11px 14px}.chips{display:flex;gap:7px}.chip{font-size:12px;padding:8px 10px;border:1px solid var(--line);background:#0a1823;color:var(--muted);border-radius:999px}.chip.active{color:#151515;background:var(--gold2)}.tablebox{border:1px solid var(--line);border-top:0;overflow:auto}table{width:100%;border-collapse:collapse;min-width:1320px}th{background:#0b1924;color:#6f8798;font-size:11px;text-align:right;padding:13px 12px;white-space:nowrap}td{padding:13px 12px;border-bottom:1px solid var(--line);font-size:13px;white-space:nowrap}tbody tr{cursor:pointer}.ticker{font-size:16px;font-weight:900}.company{font-size:11px;color:#61798b;max-width:170px;overflow:hidden;text-overflow:ellipsis}.score{display:inline-grid;place-items:center;width:43px;height:43px;border-radius:12px;font-weight:900;border:1px solid #274154}.score.hot,.good{color:var(--green);font-weight:800}.score.mid,.goldtext{color:var(--gold2);font-weight:800}.rebate{color:#5cc8ff;font-weight:800}.pill{border:1px solid #244052;padding:5px 8px;border-radius:8px}.empty{text-align:center;padding:55px;color:var(--muted)}.drawer{position:fixed;inset:0;background:#0009;display:none;z-index:50}.drawer.open{display:block}.sheet{position:absolute;left:0;top:0;height:100%;width:min(540px,94vw);background:#09151f;border-right:1px solid #22394a;padding:24px;overflow:auto}.close{float:left;background:transparent;color:#8ca0ad;border:0;font-size:26px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:10px}.mini{border:1px solid var(--line);background:#0c1a26;border-radius:14px;padding:14px}.mini span{display:block;color:var(--muted);font-size:11px}.histrow{display:grid;grid-template-columns:1.3fr .8fr .8fr .8fr;gap:8px;border-bottom:1px solid var(--line);padding:10px 0;font-size:12px}.toast{position:fixed;bottom:24px;right:24px;background:#102330;border:1px solid #2c4658;padding:13px 16px;border-radius:12px;display:none}.toast.show{display:block}@media(max-width:980px){.hero{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,1fr)}}
</style></head><body><div class="wrap"><div class="top"><div class="brand"><div class="mark">ق</div><div><h1>قنص</h1><small>Reverse Split Intelligence</small></div></div><div class="actions"><button class="btn" onclick="loadData()">تحديث العرض</button><button id="borrowBtn" class="btn gold" onclick="startBorrowSync()">تحديث Available + CTB + Rebate</button></div></div>
<section class="hero"><div class="hero-main"><div class="goldtext">QANAS / LIVE BOARD</div><h2>القنص بالركادة.</h2><p>Available وCTB وRebate من IBKR مع بيانات ما بعد التقسيم والجاهزية.</p></div><div class="syncbox"><div class="syncrow"><span>حالة البيانات</span><strong id="syncState">متصل</strong></div><div class="syncrow"><span>آخر Borrow</span><strong id="lastBorrow">—</strong></div><div class="syncrow"><span>المصدر الأساسي</span><strong>IBKR</strong></div><div class="syncrow"><span>Rebate</span><strong class="good">مفعل ✓</strong></div></div></section>
<section class="stats"><div class="stat"><span>أسهم فعالة</span><b id="sTotal">—</b></div><div class="stat"><span>Available ≤ 10K</span><b id="sScarce">—</b></div><div class="stat"><span>وصلت مستوى النصف</span><b id="sHalf">—</b></div><div class="stat"><span>قريبة من القاع ≤ 10%</span><b id="sNear">—</b></div><div class="stat"><span>جاهزية 70+</span><b id="sReady">—</b></div></section>
<section><div class="toolbar"><div class="search"><input id="q" placeholder="ابحث بالرمز أو اسم الشركة..." oninput="render()"></div><div class="chips"><button class="chip active" onclick="setFilter('all',this)">الكل</button><button class="chip" onclick="setFilter('scarce',this)">Available منخفض</button><button class="chip" onclick="setFilter('half',this)">وصل النصف</button><button class="chip" onclick="setFilter('near',this)">قريب من القاع</button></div></div><div class="tablebox"><table><thead><tr><th>السهم</th><th>الجاهزية</th><th>Available</th><th>CTB</th><th>Rebate</th><th>السعر</th><th>القاع</th><th>عن القاع</th><th>القمة</th><th>النصف</th><th>الاستقرار</th><th>4H Max</th><th>التقسيم</th></tr></thead><tbody id="rows"><tr><td colspan="13" class="empty">جاري تحميل البيانات...</td></tr></tbody></table></div></section></div>
<div id="drawer" class="drawer" onclick="if(event.target===this)closeDrawer()"><div class="sheet"><button class="close" onclick="closeDrawer()">×</button><div id="detail"></div></div></div><div id="toast" class="toast"></div><script>
let data=[],filter='all';const fmt=n=>n==null?'—':Number(n).toLocaleString('en-US',{maximumFractionDigits:2});const money=n=>n==null?'—':'$'+Number(n).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:4});const pct=n=>n==null?'—':Number(n).toFixed(2)+'%';function toast(t){const e=document.getElementById('toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),3000)}function setFilter(f,el){filter=f;document.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));el.classList.add('active');render()}async function loadData(){try{syncState.textContent='يتم التحديث...';data=await fetch('/api/hunt').then(r=>r.json());syncState.textContent='متصل';summaries();render()}catch(e){syncState.textContent='خطأ اتصال'}}function summaries(){sTotal.textContent=data.length;sScarce.textContent=data.filter(x=>x.available!=null&&x.available<=10000).length;sHalf.textContent=data.filter(x=>x.half_level_reached).length;sNear.textContent=data.filter(x=>x.distance_from_low_pct!=null&&x.distance_from_low_pct<=10).length;sReady.textContent=data.filter(x=>(x.ready_score||0)>=70).length;const d=data.map(x=>x.borrow_timestamp).filter(Boolean).sort().pop();lastBorrow.textContent=d?new Date(d+'Z').toLocaleString('ar-SA'):'—'}function render(){const q=document.getElementById('q').value.trim().toUpperCase();let a=data.filter(x=>!q||x.symbol.includes(q)||(x.company||'').toUpperCase().includes(q));if(filter==='scarce')a=a.filter(x=>x.available!=null&&x.available<=10000);if(filter==='half')a=a.filter(x=>x.half_level_reached);if(filter==='near')a=a.filter(x=>x.distance_from_low_pct!=null&&x.distance_from_low_pct<=10);a.sort((a,b)=>(b.ready_score||0)-(a.ready_score||0));rows.innerHTML=a.length?a.map(x=>`<tr onclick="openStock('${x.symbol}')"><td><div class="ticker">${x.symbol}</div><div class="company">${x.company||''}</div></td><td><span class="score ${(x.ready_score||0)>=70?'hot':(x.ready_score||0)>=50?'mid':''}">${fmt(x.ready_score)}</span></td><td class="${x.available!=null&&x.available<=10000?'good':''}">${fmt(x.available)}</td><td class="goldtext">${pct(x.ctb)}</td><td class="rebate">${pct(x.rebate_rate)}</td><td>${money(x.current_price)}</td><td>${money(x.post_split_low)}</td><td>${pct(x.distance_from_low_pct)}</td><td>${money(x.post_split_high)}</td><td><span class="pill">${money(x.half_level)} ${x.half_level_reached?'✓':''}</span></td><td>${fmt(x.stability_sessions)} / 4</td><td>${pct(x.four_hour_highest_rise_pct)}</td><td>${x.ratio}<div class="company">${x.effective_date}</div></td></tr>`).join(''):'<tr><td colspan="13" class="empty">لا توجد نتائج</td></tr>'}async function openStock(symbol){drawer.classList.add('open');detail.innerHTML='<div class="empty">جاري التحميل...</div>';try{const [s,h]=await Promise.all([fetch('/api/stock/'+symbol).then(r=>r.json()),fetch('/api/borrow/'+symbol+'/history?limit=12').then(r=>r.json())]);detail.innerHTML=`<h2>${s.symbol}</h2><div class="muted">${s.company||''} · ${s.ratio} · ${s.effective_date}</div><div class="grid2"><div class="mini"><span>Ready Score</span><b>${fmt(s.ready_score)}</b></div><div class="mini"><span>Available</span><b>${fmt(s.available)}</b></div><div class="mini"><span>CTB</span><b>${pct(s.ctb)}</b></div><div class="mini"><span>Rebate</span><b class="rebate">${pct(s.rebate_rate)}</b></div><div class="mini"><span>Current</span><b>${money(s.current_price)}</b></div><div class="mini"><span>Low</span><b>${money(s.post_split_low)}</b></div><div class="mini"><span>High</span><b>${money(s.post_split_high)}</b></div><div class="mini"><span>Half Level</span><b>${money(s.half_level)}</b></div></div><div><h3>آخر قراءات الاقتراض</h3>${h.length?h.map(r=>`<div class="histrow"><span>${r.timestamp?new Date(r.timestamp+'Z').toLocaleString('ar-SA'):''}</span><b>${fmt(r.available)}</b><b>${pct(r.ctb)}</b><b class="rebate">${pct(r.rebate_rate)}</b></div>`).join(''):'<div class="muted">لا يوجد سجل بعد</div>'}</div>`}catch(e){detail.innerHTML='<div class="empty">تعذر تحميل التفاصيل</div>'}}function closeDrawer(){drawer.classList.remove('open')}async function startBorrowSync(){borrowBtn.disabled=true;borrowBtn.textContent='جاري بدء التحديث...';try{await fetch('/api/sync/borrow/all');toast('بدأ تحديث Available و CTB و Rebate لكل الأسهم');pollBorrow()}catch(e){borrowBtn.disabled=false}}async function pollBorrow(){try{const s=await fetch('/api/sync/borrow/status').then(r=>r.json());borrowBtn.textContent=s.running?`تحديث ${s.processed}/${s.total}`:'تحديث Available + CTB + Rebate';if(s.running)setTimeout(pollBorrow,1500);else{borrowBtn.disabled=false;toast(`اكتمل التحديث: ${s.saved} قراءة جديدة`);loadData()}}catch(e){borrowBtn.disabled=false}}loadData();setInterval(loadData,120000);
</script></body></html>'''

@app.get("/", response_class=HTMLResponse)
def dashboard(): return HTMLResponse(DASHBOARD_HTML)
